module wifi_fifo (
    input wire clk,
    input wire reset,
    input wire [7:0] data_in,
    input wire write_en,
    input wire read_en,
    output reg [7:0] data_out,
    output reg full,
    output reg empty
);

reg [7:0] fifo_mem [0:3]; // FIFO memory
reg [1:0] head; // Points to the next write location
reg [1:0] tail; // Points to the next read location
reg [2:0] count; // Number of elements in the FIFO

always @(posedge clk or posedge reset) begin
    if (reset) begin
        head <= 0;
        tail <= 0;
        count <= 0;
        full <= 0;
        empty <= 1;
    end else begin
        if (write_en && !full) begin
            fifo_mem[head] <= data_in;
            head <= head + 1;
            count <= count + 1;
        end
        if (read_en && !empty) begin
            data_out <= fifo_mem[tail];
            tail <= tail + 1;
            count <= count - 1;
        end
        full <= (count == 4);
        empty <= (count == 0);
    end
end

endmodule

