module pll_2x (
    input wire clk_in,
    input wire rst,
    output reg clk_out
);

    reg [1:0] clk_div;

    always @(posedge clk_in or posedge rst) begin
        if (rst) begin
            clk_div <= 2'b00;
            clk_out <= 1'b0;
